update public.lessons l set enhancements = $ench${"industryStory":"An API used `/getUser?id=5` for reads but `/users` for creates — inconsistent and non-RESTful. New joiners kept guessing endpoints wrong. Consistent REST conventions save real time and prevent real mistakes.","visualAid":{"type":"comparison","title":"REST methods on a resource","headers":["Method","Action","Example"],"rows":[["GET","Read","GET /books/12"],["POST","Create","POST /books"],["PUT","Replace","PUT /books/12"],["PATCH","Update part","PATCH /books/12"],["DELETE","Remove","DELETE /books/12"]]},"davidTip":"When an API follows REST properly you can often guess an endpoint correctly first try. When you can't, that unpredictability is a testing risk worth writing down.","miniChallenge":"Design the five REST endpoints (method + path) for managing \"projects\".","modelAnswer":"## Example\n`GET /projects`, `GET /projects/{id}`, `POST /projects`, `PUT /projects/{id}`, `DELETE /projects/{id}`."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
