update public.lessons l set enhancements = $ench${"industryStory":"A team's end-to-end checkout suite was so flaky nobody trusted it. We moved the core checks to the API layer — they ran green in seconds on every commit, and within a week caught a tax-rounding bug that would have shipped.","visualAid":{"type":"timeline","title":"The test pyramid (bottom to top)","steps":[{"label":"Unit","detail":"many · fastest · functions"},{"label":"API / integration","detail":"fewer · fast · services talking"},{"label":"UI / end-to-end","detail":"few · slow · whole app"}]},"davidTip":"If a check can be done at the API layer, it usually should be. Speed, stability, and it runs on every build — three things UI tests struggle to give you.","miniChallenge":"Name two checks that belong at the API layer rather than the UI, and say why for each.","modelAnswer":"## Example\n1) Validating an order total — pure logic, fast and exact at the API. 2) Checking a 404 for a missing resource — trivial at the API, slow via the UI.","portfolioBuilder":"Start an \"API test strategy\" note for your portfolio: which checks you'd place at the API layer vs the UI for a sample feature, and why."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
