update public.lessons l set enhancements = $ench${"industryStory":"A team once \"secured\" an admin panel by simply not linking to it in the UI. During API testing we called the admin endpoint directly with an ordinary user's token — it returned `200 OK` and let us disable accounts. Security by obscurity is not authorisation; the URL being hard to find protects nobody with a proxy open.","visualAid":{"type":"comparison","title":"Authentication vs authorisation","headers":["","Authentication","Authorisation"],"rows":[["Question","Who are you?","What can you do?"],["Checks","Identity / credentials","Permissions / roles"],["Failure code","401 Unauthorized","403 Forbidden"],["Happens","Once, at login","On every request"],["Analogy","Showing your passport","Which doors your keycard opens"]]},"davidTip":"The naming trips everyone up: `401` literally reads \"Unauthorized\" but means *unauthenticated*. I still say it out loud to myself — 401 is \"who?\", 403 is \"no\". It sticks.","miniChallenge":"Write, in your own words, one real example of an authentication failure and one of an authorisation failure from an app you use.","modelAnswer":"## Example\nAuthentication failure: my session expired, so the app returned `401` and bounced me to the login screen. Authorisation failure: I'm logged in fine, but clicking \"Admin settings\" returned `403` because my account is a standard user.","resourcePreview":{"name":"Auth Concepts Cheat Sheet","purpose":"One page separating authentication, authorisation, 401 and 403.","whenToUse":"Keep it open through Module 5.","formats":["PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 5 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A partner integration failed intermittently, so a developer \"helpfully\" logged the full request headers to debug it. Weeks later a routine log review found thousands of `Authorization: Basic` headers sitting in a searchable log store — every one decodable to a live password. We rotated every credential overnight. Logging auth headers is how quiet breaches happen.","visualAid":{"type":"comparison","title":"API keys vs Basic auth","headers":["","API Key","Basic Auth"],"rows":[["Sends","A secret string","username:password (base64)"],["Where","Header or query param","Authorization header"],["Identity","Often just \"a caller\"","A specific user"],["Protection","HTTPS only","HTTPS only"],["Main risk","Key leaks = full access","Decoded password if not HTTPS"]]},"davidTip":"Any time I see credentials in a query string — `?api_key=...` — I flag it. URLs get logged by servers, proxies and browser history far more than headers do. Push secrets into headers, always over HTTPS.","badGood":{"label":"sending an API key","bad":"`GET /orders?api_key=live_9f8a...` — the secret sits in the URL, where it ends up in server logs and browser history.","good":"`GET /orders` with header `x-api-key: live_9f8a...` over HTTPS — the secret stays out of the URL and out of most logs."},"miniChallenge":"Base64-encode the string `admin:secret` (any online encoder or Postman will do), then decode it back. Note how many steps it took to reveal the password.","modelAnswer":"## Example\n`admin:secret` encodes to `YWRtaW46c2VjcmV0`. Decoding takes one step and returns `admin:secret` in full — demonstrating that base64 offers no confidentiality on its own; the security comes entirely from HTTPS."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 5 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"On one project the login endpoint issued JWTs, but nobody had set an expiry — the `exp` claim was simply missing. A token stolen from a laptop would have worked forever. We only found it because a tester decoded the token at jwt.io out of curiosity and asked \"where's the expiry?\" That one question closed a serious hole.","visualAid":{"type":"comparison","title":"The three parts of a JWT","headers":["Part","Contains","Tester note"],"rows":[["Header","Algorithm (e.g. HS256)","Watch for \"alg\": \"none\""],["Payload","Claims: sub, role, exp","Readable — no secrets here"],["Signature","Cryptographic seal","Tamper the token → it must fail"]]},"davidTip":"A bearer token is a password in disguise — \"bearer\" literally means whoever holds it gets in. So I test what happens when it leaks: expired token, tampered token, no token. If any of those returns `200`, that's a finding, not a footnote.","badGood":{"label":"JWT payload contents","bad":"The payload includes `\"password\": \"hunter2\"` and `\"cardNumber\": \"4111...\"` — both fully readable by anyone who decodes the token.","good":"The payload includes only `sub`, `role` and `exp` — an identifier and permissions, never secrets, because the payload is not encrypted."},"miniChallenge":"Take any JWT (from jwt.io's default example), decode it, and write down its `exp` value. Then say what status you'd expect if you sent it after that time had passed.","modelAnswer":"## Example\nThe decoded payload shows `\"exp\": 1516239022`. That timestamp is long past, so a well-behaved API should reject the token with `401 Unauthorized` and the client should use a refresh token to obtain a new one."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 5 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"An integration requested the scope `read:profile` on the consent screen, but the token it received also worked against `write:orders`. A tester spotted it by taking the \"read-only\" token and firing a `POST /orders` at the resource server — it succeeded. The auth server was over-issuing scopes. Reading the consent screen and then actually testing the token's limits is what caught it.","visualAid":{"type":"timeline","title":"OAuth 2.0 authorisation code flow","steps":[{"label":"Redirect","detail":"client sends user to the authorisation server"},{"label":"Consent","detail":"user logs in and approves the scopes"},{"label":"Code","detail":"auth server returns an authorisation code"},{"label":"Exchange","detail":"client swaps code + secret for an access token"},{"label":"Call","detail":"client hits the resource server with Bearer token"}]},"davidTip":"Don't get lost in the diagrams. As a tester you care about three things: does the token only grant the scopes consented to, does it expire, and does the resource server actually enforce those scopes. Everything else is the developers' problem.","miniChallenge":"For a \"Log in with GitHub\" flow, list the four players by name (resource owner, client, authorisation server, resource server) and say who GitHub is playing.","modelAnswer":"## Example\nResource owner: me. Client: the third-party app I'm signing into. Authorisation server: GitHub's OAuth login and consent screen. Resource server: GitHub's API holding my repos. GitHub plays both the authorisation server and the resource server here.","resourcePreview":{"name":"OAuth 2.0 Flow Diagram","purpose":"A printable map of the players and the token exchange.","whenToUse":"Reference it whenever an API says \"OAuth\" or \"Bearer\".","formats":["PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 5 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"On a healthcare portal, a tester logged in as an ordinary patient and simply incremented the id in `GET /patients/{id}/records`. Every record came back — thousands of other patients' data, no `403` in sight. The UI only ever showed you your own records, so it had \"looked fine\" for months. One id swap in Postman turned a green release into a critical incident. That's the power of testing authorisation directly.","visualAid":{"type":"comparison","title":"Access-control test matrix","headers":["Who sends it","Endpoint","Expected"],"rows":[["No token","/orders","401"],["Standard user","/admin/users","403"],["User 42","/users/42/data","200"],["User 42","/users/43/data","403 or 404"],["Admin","/admin/users","200"]]},"davidTip":"Give me a low-privilege token and ten minutes in Postman, and I'll tell you whether an API is actually secure. Swapping ids and calling admin routes directly finds more real bugs than any amount of clicking around the UI ever will.","badGood":{"label":"authorisation testing","bad":"You test `GET /users/42/data` as user 42, see `200`, and move on — the whole suite runs as the correct owner.","good":"You also run `GET /users/43/data` as user 42 and assert it is *not* `200`, plus an admin route as a standard user asserting `403`. The negatives are where the bugs live."},"miniChallenge":"List three requests you'd send to check access control on `GET /orders/{id}`, and the status you'd expect from each.","modelAnswer":"## Example\n1) No token → expect `401`. 2) A valid user requesting their own order id → expect `200`. 3) The same user requesting another customer's order id → expect `403` or `404`, never `200` (a `200` here is BOLA).","portfolioBuilder":"Add an \"Access control\" folder to your Postman collection with a happy-path and an attacker request for one endpoint, each with a test script. This demonstrates security-aware testing to any hiring manager."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 5 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A fintech client's `GET /account` returned a tidy UI but, buried in the JSON, every response also carried the customer's full `sortCode`, `accountNumber` and an internal `riskScore` the business never intended to expose. The frontend used none of it. A tester reading the *whole* body — not just the visible fields — flagged it against OWASP \"Excessive Data Exposure\", and the API was trimmed before launch. The bug was invisible to anyone who only watched the screen.","visualAid":{"type":"comparison","title":"OWASP risks → tester actions","headers":["Risk","What to send","Red flag"],"rows":[["BOLA","Swap id to another user's","200 with their data"],["Broken auth","Expired / tampered token","Still returns 200"],["Excessive data","Normal GET, read all fields","passwordHash / PII present"],["No rate limiting","Repeat POST /login fast","No lockout or throttle"],["Misconfiguration","Trigger an error","Full stack trace / secrets"]]},"davidTip":"You don't need to be a security specialist to be dangerous with OWASP. I've watched functional testers become the most valued people on the team simply by turning the Top 10 into ten saved requests and running them on every release. Do that and you'll find bugs the developers didn't know existed.","badGood":{"label":"reviewing a response body","bad":"You confirm the three fields the UI needs are present, see `200`, and pass the test — the other twelve fields go unread.","good":"You read every field in the body and challenge each one: the response leaks `passwordHash` and `internalRiskScore`, so you raise an excessive-data-exposure finding with the payload attached."},"miniChallenge":"Choose one OWASP risk from this lesson and write out the single Postman request you'd send to test for it, plus what result would make it a finding.","modelAnswer":"## Example\nRisk: Broken authentication. Request: resend a known-good request but with an expired bearer token. A finding is any `2xx` response — the API should reject the dead token with `401`. I'd save it as \"Broken auth — expired token\" in my OWASP folder.","managersReview":{"intro":"If I reviewed your Module 5 security work as a lead, here's what I'd assess:","strengths":["You separate authentication (401) from authorisation (403) cleanly","You write negative tests, not just happy paths","You test tokens for expiry and tampering"],"improvements":["Turn each OWASP risk into a saved, repeatable request","Add assertions so negatives fail loudly in CI","Attach the actual response body as evidence in findings"],"gaps":["Only testing as the correct, privileged user","Never swapping ids to check for BOLA","Reading only the fields the UI happens to use"]},"portfolioBuilder":"Build an \"OWASP API Security checks\" Postman folder: one saved, asserted request per risk from this lesson (BOLA, broken auth, excessive data, rate limiting, misconfiguration). Export it as your Module 5 portfolio artefact — it's concrete proof of security-aware testing.","resourcePreview":{"name":"OWASP API Top 10 Tester Checklist","purpose":"Each OWASP risk mapped to a concrete request and a red-flag result.","whenToUse":"Run it against every API you test, on every release.","formats":["PDF","Postman JSON"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 5 and l.lesson_number = 6;

