-- ============================================================
-- Lesson enhancements for "api-testing-masterclass" Module 6.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/api-module6.mjs and regenerate. Run AFTER
-- lesson-enhancements-schema.sql and the lesson seeds. Idempotent.
-- ============================================================

update public.lessons l set enhancements = $ench${"industryStory":"A team I joined had 400 API tests — 380 of them hammered a read-only `GET /catalogue` endpoint, and just 20 touched checkout. Their coverage number looked great, yet a payment bug shipped. We re-ranked by risk, cut the catalogue tests, and tripled the checkout coverage. Fewer tests, far more protection.","visualAid":{"type":"comparison","title":"Risk-ranking endpoints","headers":["Endpoint","Impact if broken","Priority"],"rows":[["POST /orders","Takes money — critical","High"],["PUT /users/{id}","Corrupts stored data","High"],["GET /products","Customer sees wrong list","Medium"],["GET /health","Monitoring only","Low"]]},"davidTip":"I always start a new API by writing the endpoints on one page and scoring each out of ten for risk. That page becomes my plan. It takes twenty minutes and it stops me wasting days testing things that barely matter.","miniChallenge":"Pick any public API you know and write its three highest-risk endpoints in priority order, one line of reasoning each.","modelAnswer":"## Example\n1) `POST /api/login` — auth failure locks everyone out. 2) `POST /api/users` — creates records; bad data spreads downstream. 3) `GET /api/users` — read-only, lower blast radius, still customer-facing.","resourcePreview":{"name":"API Risk-Ranking Template","purpose":"A one-page grid to score endpoints by likelihood and impact.","whenToUse":"Fill it in before you start testing any new API.","formats":["PDF","XLSX"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 6 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A checkout API happily returned `200 OK` when the price field was missing — it just stored `£0.00`. Every happy-path test passed. The first negative test we wrote — \"send it with no price\" — turned green when it should have been red, and we'd found a live money-losing bug in ten minutes.","visualAid":{"type":"comparison","title":"Positive vs negative testing","headers":["Aspect","Positive","Negative"],"rows":[["Input","Valid","Invalid / missing / malicious"],["Expected status","2xx","4xx"],["Proves","It works when right","It fails safely when wrong"],["Finds","Basic breakage","Most real defects"]]},"davidTip":"When I interview testers, I ask them to test a login. The ones who only try correct credentials get a polite nod. The ones who ask \"what if the password is empty, or 5000 characters, or contains SQL?\" get the job.","badGood":{"label":"a negative test","bad":"Sends a bad payload, sees an error, marks the test passed — never checks whether it was a `400` or a `500`.","good":"Sends a bad payload and asserts exactly `400 Bad Request` with an error body naming the missing field."},"miniChallenge":"Take any `POST` endpoint on reqres.in and write three negative cases: a missing field, a wrong data type, and an empty body. Predict each status code before you send it.","modelAnswer":"## Example\nMissing field → `400`; wrong type → `400`; empty body → `400`. On reqres.in the register/login endpoints return `400` with a descriptive `error` message; a `500` on any of these would be a defect worth raising."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 6 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A booking API let you reserve up to 10 seats. The developer wrote `if (seats > 10) reject` — so 10 worked, and 11 failed, but nobody tested the boundary. Turned out a separate rule capped it at 9, and `10` silently double-booked. One boundary test at exactly the limit found a bug that had been live for months.","visualAid":{"type":"comparison","title":"Equivalence partitions for age (valid 18–65)","headers":["Partition","Example value","Expected"],"rows":[["Below range","17","Reject (400)"],["In range","40","Accept (2xx)"],["At lower edge","18","Accept"],["At upper edge","65","Accept"],["Above range","66","Reject (400)"]]},"davidTip":"The three questions I ask of any field: what's the smallest legal value, what's the largest, and what happens one step beyond each? Answer those and you've found most of the bugs before you've finished your coffee.","badGood":{"label":"testing a numeric limit","bad":"Tests `page=2` and `page=3` — both comfortably valid — and declares pagination covered.","good":"Tests `page=0`, `page=1`, the last valid page, and one page beyond it, asserting status and whether `data` is empty."},"miniChallenge":"Pick any field with a limit (a length, a range, a page size) and list the exact values you'd test around its boundary. Aim for five values.","modelAnswer":"## Example\nFor a username limited to 20 characters: test lengths `0`, `1`, `19`, `20`, `21`. Zero checks empty handling; 19–21 straddle the boundary to expose a `<` vs `<=` error."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 6 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A team's `POST /accounts` returned a proud `201 Created` on every call, and their tests passed for months. A CRUD flow — create then immediately read back — revealed the write was being swallowed by a broken queue: the `201` was a lie and nothing persisted. One `GET` after the `POST` would have caught it on day one.","visualAid":{"type":"timeline","title":"A full CRUD flow","steps":[{"label":"Create","detail":"POST /users → 201 + new id (save it)"},{"label":"Read","detail":"GET /users/{id} → 200 + your data"},{"label":"Update","detail":"PUT /users/{id} → 200 + changed fields"},{"label":"Delete","detail":"DELETE /users/{id} → 204"},{"label":"Confirm","detail":"GET /users/{id} → 404 (gone)"}]},"davidTip":"I chain the created id into a Postman collection variable every single time. It turns four separate requests into one honest story, and it means my tests never rely on data someone else might have deleted.","badGood":{"label":"a CRUD test","bad":"Sends a `POST`, sees `201`, and stops — the record may never have persisted and the id is thrown away.","good":"Saves the id, reads it back, updates it, deletes it, then confirms a final `GET` returns `404` — proving every step."},"miniChallenge":"Build the CRUD flow, then add one assertion to the Read step that checks a field you sent in Create actually came back unchanged.","modelAnswer":"## Example\nIn the `GET` step's test tab: `pm.test('name persisted', () => pm.expect(pm.response.json().name).to.eql('Ada'));`. This proves the Create not only returned `201` but stored the value correctly."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 6 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"An API quietly changed `price` from a number (`9.99`) to a string (`\"9.99\"`). Every value assertion still passed — the value looked right. A downstream service that did maths on it broke in production. After that we added a schema check on every response, and a type change like that could never sneak past again.","visualAid":{"type":"comparison","title":"What each assertion catches","headers":["Assertion","Catches","Example"],"rows":[["Status","Wrong outcome","Expected 200, got 500"],["Body value","Wrong data","name is \"Bob\" not \"Ada\""],["Schema","Wrong shape/type","price is a string not a number"],["Header","Wrong metadata","Content-Type is text/html"],["Response time","Slow regression","Took 4s, limit was 1s"]]},"davidTip":"My rule for a \"done\" API test: it asserts the shape as well as the value, and I have watched it fail at least once. A test I've never seen go red is a test I don't trust.","badGood":{"label":"a response assertion","bad":"`pm.response.to.have.status(200);` — and nothing else. Passes on an empty body, a renamed field, or a wrong type.","good":"Checks status, asserts `data.email` equals the expected value, validates the JSON schema, and asserts `responseTime` is under 1000ms."},"miniChallenge":"Add a JSON schema assertion to a reqres.in `GET /api/users/2` request that requires `data.id` to be a number and `data.email` to be a string. Break the type in the schema and watch it fail.","modelAnswer":"## Example\n`const schema = { type:'object', properties:{ data:{ type:'object', required:['id','email'], properties:{ id:{type:'number'}, email:{type:'string'} } } } };`\n`pm.test('schema', () => pm.response.to.have.jsonSchema(schema));`"}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 6 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A fintech API I audited returned a `500` with a full Java stack trace whenever a field was missing — exposing framework versions, class names and a database table. It was two bugs in one: it should have been a `400`, and it should never have leaked internals. We reported it as a security issue, not just a test failure. That's the difference between a tester and a senior tester.","visualAid":{"type":"comparison","title":"Reading error responses","headers":["Scenario","Correct response","Red flag"],"rows":[["Missing field","400 + clear message","500, or silent 200"],["No auth token","401 Unauthorized","500, or 200 with data"],["Unknown resource","404 Not Found","500, or empty 200"],["Malformed JSON","400 Bad Request","500 + stack trace (leak)"]]},"davidTip":"When I test error handling I always read the body, not just the code. A `400` that says \"invalid\" tells me nothing; a `400` that says \"email must be a valid address\" tells the client exactly how to fix it. And if I ever see a stack trace in a response, I stop testing and raise a security ticket.","badGood":{"label":"error-handling assessment","bad":"Sends a bad payload, sees a `500`, records \"returns an error — pass\". Misses that a `500` on client input is a defect and that the body leaks internals.","good":"Asserts exactly `400`, reads the body for a clear actionable message, and flags any leaked stack trace as a security risk."},"miniChallenge":"Send genuinely malformed JSON (e.g. `{\"email\":`) to a reqres.in `POST` endpoint. Record the status and body, and judge: is it a clean `4xx`, and is the message safe to show a user?","modelAnswer":"## Example\nMalformed JSON should return `400 Bad Request` with a generic message like \"Invalid request body\" — no stack trace, no internal paths. A `500` here would be a robustness bug; a leaked stack trace would be a security finding. Record both the status and the exact body so the developer can reproduce it.","managersReview":{"intro":"If I reviewed your REST testing work as a lead at the end of this module, here's what I'd look for:","strengths":["A risk-ranked strategy driving where effort goes","Positive AND negative tests, with exact status assertions","Full CRUD flows that chain ids and clean up after themselves","Assertions on status, body, schema, headers and response time","Error tests that distinguish 4xx from 5xx and judge the message"],"improvements":["Add response-time assertions to catch silent performance regressions","Standardise your expected-error shapes across the collection","Add schema validation to every read to catch type drift"],"gaps":["Only happy-path coverage with no negatives","Trusting a 2xx without reading the body back","Accepting a 500 on bad input as \"an error, so it passes\"","Never noticing an error response that leaks internal detail"]},"portfolioBuilder":"Build a \"REST API Test Suite\" Postman collection against reqres.in for your portfolio: a full CRUD flow with chained ids, a set of positive and negative tests with exact status assertions, boundary tests on pagination, schema validation on reads, and an error-handling folder covering 400/401/404 with judged messages. Export the collection JSON — this is a strong Module 10 artefact.","resourcePreview":{"name":"REST Testing Assertion Library","purpose":"Copy-paste Postman test snippets for status, body, schema, headers, response time and common error checks.","whenToUse":"Reach for it whenever you build a new REST test in Postman.","formats":["JSON","PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 6 and l.lesson_number = 6;

